We will now bring together all of the structural results established in the previous sections to formally prove \cref{th:stability}. That is, assuming \boxedchar{A1}, \boxedchar{A2}, \boxedchar{A3}, we want to show that $\hat K_3-\varsigma$ is stable with respect to $\mathcal{G}^{(c)}_{\operatorname{ex}}$.
 More specifically, we assume that $\hat{K}_3 - \varsigma$ is a tight positive algebra element satisfying $\hat{K}_3 - \varsigma \ge s(\hat K_{3,1} + \hat K_{3,3})$. Writing

\begin{equation*}
    \varsigma_n = \min_{F \in \mathcal{F}_n^\varnothing} p(\hat{K}_3; F),
\end{equation*}

where clearly $\lim_{n \to \infty} \varsigma_n = \varsigma$, we want to prove that there exists some $n_0$ so that for any given $\varepsilon > 0$ there exists some $\delta>0$ so that any given $G \in F^\varnothing$ satisfying $p(\hat K_3,G) < \varsigma_n + \delta$ can be turned into an element of $\mathcal{G}^{(c)}_{\operatorname{ex}}$ as defined in \cref{sec:formal_statement_theorem} by recoloring at most a $\varepsilon$ fraction of all edges.

\medskip

We start by noting that we may always assume

\begin{equation} \delta <
    \frac{\varepsilon_4}
    {2\left(\frac{1}{\varepsilon_1(1+\varepsilon_1)}+\frac{\binom{n_1}{6}}{s}\right)}
\end{equation}
which implies that
\boxedchar{A4} is satisfied. Let the set $C_1\cup \dots \cup C_r=W\subseteq V(G)$ as well as $E\in\mathcal{L}_{\operatorname{ex}}^{(c)}$ be as given by \cref{lem:Claim_7} and $E_0$, $V_0$, $F_i$, and $V_i$ be as given by \cref{eq:E0V0FiVi}. Write
$
    V^\ast=V(G)\setminus \bigcup_i V_i.    
$
and let $E^\ast$ be all pairs $(x,y)$ where $x\in V_i$ and $y\in V_j$  such 
that $G(\{x,y\})\ne E(\{i,j\})$. Note that by \cref{lem:Claim_8}

\begin{equation}
    |V^\ast| \le n - \sum_{i\in [r]}|V_i|\le \varepsilon_7n. \end{equation}

The goal is to recolor a sufficiently small number of edges in $G$ such that $V^\ast = \emptyset$ as well as $E^\ast = \emptyset$, establishing the claim of \cref{th:stability}. Each of the subsequent claims will recolor some edges without increasing the number monochromatic triangles. After each claim,
we will assume that we have recolored the edges in $G$ accordingly and update both $E^\ast$ and $V^\ast$.

\begin{claim} We  can turn all $G[V_i]$ into monochromatic cliques with
    the loop color of $E$ by recoloring at most

    \begin{equation*}
        \frac{r}{3}(p(\hat K_3,G)-\varsigma_n)\binom{n}{2} \end{equation*}

    edges.
\end{claim}
\begin{proof}
    Recoloring any individual edge $\{v,w\} \in G[V_i]$ with $G(\{v,w\}) \neq E(\{i\})$ to the correct color creates no more than

    \begin{align*}
       &|V^\ast|+|V_i| + \sum_{j \neq i} (|V_j|-|F_j|) + |F_j|(1-\delta_0) \le \left(1 - \delta_0\left(1-\frac{1}{r}\right)(1-\varepsilon_7)\right)n 
    \end{align*}
    new monochromatic triangles, where we have used \cref{lem:Claim_8} to lower bound the $|F_j|$.

































    On the other hand, the number of destroyed triangles is at least
    \[
        \sum_{\substack{j \neq i\\E(\{i,j\})=G(\{v,w\})}}
        (2\delta_0-1)|F_j|
        \ge 2(2\delta_0-1)\frac{1-\varepsilon_7}{r}n,
    \]
    where we have used \cref{lem:Degree_at_lest_two} so that the summation has at least two summands as well as \cref{lem:Claim_8} to lower bound the $|F_j|$.
    The difference
    between the destroyed and created triangles
    is therefore at least

    \begin{align*}
         &\left((4\delta_0-2)\frac{1-\varepsilon_7}{r}-1 + \delta_0\left(1-\frac{1}{r}\right)(1-\varepsilon_7)\right)n \\
         &=\left(\delta_0-1+\frac{5\delta_0-2}{r}+\left(-\delta_0\left(1-\frac{1}{r}\right) -\frac{4\delta_0-2}{r} \right)\varepsilon_7 \right)n \ge \frac{n}{r}
    \end{align*}
    where the lower bound holds for \whiteboxedchar{sufficiently large $\delta_0$} and \whiteboxedchar{sufficiently small $\varepsilon_7$}. Recoloring more than 
    $r\binom{n}{2}(p(\hat K_3,G)-\varsigma_n)/3$ edges would therefore destroy more than $\binom{n}{3}(p(\hat K_3;G)-\varsigma_n)$ triangles, a contradiction.










\end{proof}



