Let us show that we now may assume that

\begin{equation}
    E^\ast \subseteq E_0 .
\end{equation}

For any $(x,y)\in E^\ast$ with $x\in V_i$ and $y\in V_j$ we know that $i \neq j$ by \cref{lem:Claim_10}.
Let us show that $G[\{x,y\}\cup W]$ does not embed into $E$ so that $(x,y) \in E_0$. If it were embeddable, then $x$ would get assigned to the same vertex in $E$ as the class $C_i$ and $y$ to the same vertex as $C_j$ because the edges in $x\ast C_i$ and $y\ast C_j$ are monochromatic
with the loop color of $E$  by \cref{lem:Claim_10}.
By assumption though, $G(\{x,y\})\ne E(\{i,j\})$, which contradicts the embedding.




As a notational convenience,
given a vertex $v\in V(G)$ as well as a set $V_i$ and color $c_1\in [c]$,
denote by $G[v,V_i,c_1]$ the number of $c_1$-colored edges between $v$ and $V_i$ in $G$.

\begin{claim} We can ensure $V^\ast = \emptyset$ by recoloring at most

    \begin{equation*}
    2^2 8^2(c-1)^2r^2(p(\hat K_3; G)-\varsigma_n)\binom{n}{2}
    \end{equation*}

   edges.
\end{claim}

\begin{proof}
    Let $v \in V^\ast$ and $i^\ast = i^\ast(v)$ a corresponding index that minimizes $|V_i|$. Let us consider the recoloring obtained by recoloring all edges of $v\ast V_j$ to $E(\{i,j\})$, that is we add $v$ to $V_i$. We will execute this recoloring iteratively until $V^\ast = \emptyset$ and argue that at each step we are reducing the overall number of monochromatic triangles, implying an upper bound on $|V^\ast|$. The only ingredients that will be used in each step are the lower bounds for the $|V_i|$ from \cref{lem:Claim_8}, the upper bound on $|E^\ast|$ due to \cref{eq:f2} and \cref{lem:bound_for_zerosets}
    and the upper bound for $|V^\ast|$ due to \cref{eq:Vastupperbnd}.
    Trivially these will remain true under the recoloring throughout all iterations. We note that $i^\ast$ is not fixed but updated at each iteration.

    Let $t_v^{(b)}$ and $t_v^{(a)}$ therefore denote the number of monochromatic triangles incident to $v$ in $G$ \emph{before} and \emph{after} recoloring. We have

    \begin{equation} t_v^{(a)} \leq \binom{|V_{i^\ast}|}{2}   + |E^\ast| + |V^\ast| \, n
        \le
        \left(\frac{1}{2r^2}+\varepsilon_5+\varepsilon_7\right)n^2,
    \end{equation}

    where we have used the upper bounds for $V^*$ and  $E^*$.


























    We can lower bound $t_v^{(b)}$ by counting those triangles incident to $v$ with both end points in $G\setminus V^\ast$, that is

    \begin{equation} t_v^{(b)} \ge 
     \sum_{j\le k}
        G[v,V_j,E(\{j,k\})] \, G[v,V_k, E(\{j,k\})]
        \cdot\begin{cases}
            \frac{1}{2} \text{ if } j=k \\
            1 \text{ otherwise }
        \end{cases}-\varepsilon_5n^2
        -r n,
    \end{equation}

    where the term $\varepsilon_5n^2$ accounts for $|E^*|$, the term $-r n$ 
    arises from the fact that we are 
    overcounting, and the coefficient $1/2$ from the fact that
    \[
        \binom{G[v,V_j, E(j)]}{2}
        \ge
        \frac{1}{2} \, G[v,V_j, E(j)]^2 - n.
    \]
    Our task is therefore to lower bound
    \cref{eq:basic_lower_bound} and compare it to the upper bound of $t_v^{(a)}$.

    We view the summation in \cref{eq:basic_lower_bound} as a degree 2 polynomial over $cr$ variables $x_{j,d}$ corresponding to $G[v,V_j,d]$ ranging over integers subject to the constraints that all variables are $\ge 0$ and that $|V_j| = \sum_{d} x_{j,d}$. Expressed like this, we are trying to lower bound

    \begin{equation} \sum_{j\le k}
        x_{j,E(\{j,k\})} x_{k,E(\{j,k\})}
        \cdot\begin{cases}
            \frac{1}{2} \text{ if } j=k \\
            1 \text{ otherwise }
        \end{cases}.
    \end{equation}

    \cref{alg:decrease_triangles} now takes a feasible assignment for \cref{eq:polynomial_to_lower_bound} and produces another feasible assignment with smaller support and attaining a smaller value. The goal is to find a feasible assignment for which we can explicitly compute a lower bound which therefore also lower bounds the original assignment.

    \begin{algorithm}
    \caption{Find a minimal assignment for \cref{eq:polynomial_to_lower_bound}} \begin{algorithmic}
    \REQUIRE $x_{i,d}\in\mathbb N$ with $\sum_{d}x_{i,d} = |V_i|$, loop color $c_\ell$ in $E$, enumeration $i_1,...,i_r$ of $V(E)$.


    \FOR{k=1,\dots,r}
        \STATE $d^*\gets arg\,min_{d\in[c]} \begin{cases} \frac{1}{2}|V_{i_k}|&\text{if $d=c_\ell$} \\ \sum_{E(\{i_k,j\})=d} x_{j,d}&\text{otherwise} \end{cases}$
        \FOR{ $d\in [c]$}
            \IF{ $d \ne d^*$}
                \STATE $x_{i_k,d} \gets 0$
            \ELSE
                \STATE $x_{i_k,d} \gets |V_{i_k}|$
                \STATE $\alpha(i_k)=d$
            \ENDIF
        \ENDFOR
    \ENDFOR
    \RETURN $\alpha$
    \end{algorithmic}
    \end{algorithm}

    Take the given assignment $x_{i,d} = G[v,V_i,d]$ as input to the algorithm.
    By \cref{lem:two_disjoint_monochrom} we have exactly four cases to consider.
    \begin{enumerate}
        \item For at least two different $i,j\in [r]$ we have ${\alpha(i)}=c_\ell = {\alpha(j)}$. In this case \cref{eq:basic_lower_bound} is lower bounded by 

    \begin{equation} \left(\frac{1-\varepsilon_7}{r}\right)^2 n^2 -\varepsilon_5n^2-rn.
    \end{equation}





















        \item  There exists no $i$ such that $\alpha(i)=c_\ell$. Then, by maximality of the Ramsey graph, there exists a monochromatic triangle in $E$ extended by $v$ through $\alpha$, giving the lower bound

    \begin{equation} \left(\frac{1-\varepsilon_7}{r}\right)^2n^2 - \varepsilon_5n^2-rn.
    \end{equation}














        \item There exists an $i$ such that $\alpha(i)=c_\ell$ and there exist two points $x,y\in V(E)$ so that $\alpha(x)=E(x,y)=\alpha(y)$. In this case we again get the lower bound

    \begin{equation} \left(\frac{1-\varepsilon_7}{r}\right)^2 n^2-\varepsilon_5n^2-rn.
    \end{equation}















        \item There exists a vertex $u$ so that $E[u,\alpha^{-1}(d)]$ has color $d$ for all $d\in [c]$.























    \end{enumerate}

    The last case does not have an immediate lower bound. Assume therefore that \emph{every enumeration} of $V(E)$ in \cref{alg:decrease_triangles}
    results in  \cref{enum:case_4_alg}. We therefore consider two cases.

    \medskip
    \noindent \textbf{Case 1. }     Assume that for every $w\in V(E)$ there exists an enumeration $i_1,\dots,i_r$ of $V(E)$ so that 
    $i_r=w$ and so that 
    $w$ is not the vertex $u$ from \cref{enum:case_4_alg}. 
For each $w$, by definition of \cref{alg:decrease_triangles},
we may lower-bound $t_v^{(b)}$ by considering the situation when the $r-1$-st iteration of \cref{alg:decrease_triangles} is completed and before we determine the value of all $x_{i_r,d}$ in the $r$-th and last iteration. Since we are in case \cref{enum:case_4_alg}, there exists a vertex $u$ so that
$v\ast V_x$ is assigned the color $E(\{ u,x\})$ for all $x\ne w$. Hence we may lower bound $t_v^{(b)}$ by
\begin{equation} \binom{|V_u|}{2} + \frac{1}{2} G[v,V_w,E(\{w\})]^2 + \sum_{\substack{x\in V(E)\setminus\{u,w\} \\ E(\{w,x\}) = E(\{u,x\})}}|V_x| G[v,V_w,E(\{u,x\})] -\varepsilon_5n^2-rn.
\end{equation}
By \cref{lem:exists_cherry_in_Ramsey}, for every color $d\in [c]\setminus \{E(\{u,w\})\}$, the term $G[v,V_w,d]$ occurs in \cref{eq:last_step_lower_bound}. 
We assume that for all $w\in V(E)$ with respectively $u\in V(E)$ we have that, $G[v,V_w,E(\{u,w\})]\ge \frac{7}{8} |V_w|$. Otherwise, we get the lower bound
\begin{equation} \text{\cref{eq:last_step_lower_bound}} \ge 
    \left(\frac{1}{2} + \frac{1}{2\cdot 8^2(c-1)^2}\right)\left(\frac{1-\varepsilon_7}{r}\right)^2n^2 
    -\varepsilon_5 n^2 -rn.
\end{equation}
Then, there exists a unique function
$\alpha:V(E)\to[c]$ indicating that for each $w\in V(E)$, the set $v\ast V_w$ has at least $\frac{7}{8}|V_w|$ edges of color $\alpha(w)$. But by the maximality of the Ramsey graph, there will exist $u,w\in V(E)$ so that $\alpha(u)=E(\{u,w\}) = \alpha(w)$. Hence, we may lower bound $t_v^{(b)}$ by

\begin{equation} \frac{9}{16} \left(\frac{1-\varepsilon_7}{r}\right)^2n^2.
\end{equation}




    \medskip
