    \RETURN $\alpha$
    \end{algorithmic}
    \end{algorithm}

    Take the given assignment $x_{i,d} = G[v,V_i,d]$ as input to the algorithm.
    By \cref{lem:two_disjoint_monochrom} we have exactly four cases to consider.
    \begin{enumerate}
        \item For at least two different $i,j\in [r]$ we have ${\alpha(i)}=c_\ell = {\alpha(j)}$. In this case \cref{eq:basic_lower_bound} is lower bounded by 

    \begin{equation} \left(\frac{1-\varepsilon_7}{r}\right)^2 n^2 -\varepsilon_5n^2-rn.
    \end{equation}





















        \item  There exists no $i$ such that $\alpha(i)=c_\ell$. Then, by maximality of the Ramsey graph, there exists a monochromatic triangle in $E$ extended by $v$ through $\alpha$, giving the lower bound

    \begin{equation} \left(\frac{1-\varepsilon_7}{r}\right)^2n^2 - \varepsilon_5n^2-rn.
    \end{equation}














        \item There exists an $i$ such that $\alpha(i)=c_\ell$ and there exist two points $x,y\in V(E)$ so that $\alpha(x)=E(x,y)=\alpha(y)$. In this case we again get the lower bound

    \begin{equation} \left(\frac{1-\varepsilon_7}{r}\right)^2 n^2-\varepsilon_5n^2-rn.
    \end{equation}















        \item There exists a vertex $u$ so that $E[u,\alpha^{-1}(d)]$ has color $d$ for all $d\in [c]$.























    \end{enumerate}

    The last case does not have an immediate lower bound. Assume therefore that \emph{every enumeration} of $V(E)$ in \cref{alg:decrease_triangles}
    results in  \cref{enum:case_4_alg}. We therefore consider two cases.

    \medskip
    \noindent \textbf{Case 1. }     Assume that for every $w\in V(E)$ there exists an enumeration $i_1,\dots,i_r$ of $V(E)$ so that 
    $i_r=w$ and so that 
    $w$ is not the vertex $u$ from \cref{enum:case_4_alg}. 
For each $w$, by definition of \cref{alg:decrease_triangles},
we may lower-bound $t_v^{(b)}$ by considering the situation when the $r-1$-st iteration of \cref{alg:decrease_triangles} is completed and before we determine the value of all $x_{i_r,d}$ in the $r$-th and last iteration. Since we are in case \cref{enum:case_4_alg}, there exists a vertex $u$ so that
$v\ast V_x$ is assigned the color $E(\{ u,x\})$ for all $x\ne w$. Hence we may lower bound $t_v^{(b)}$ by
\begin{equation} \binom{|V_u|}{2} + \frac{1}{2} G[v,V_w,E(\{w\})]^2 + \sum_{\substack{x\in V(E)\setminus\{u,w\} \\ E(\{w,x\}) = E(\{u,x\})}}|V_x| G[v,V_w,E(\{u,x\})] -\varepsilon_5n^2-rn.
\end{equation}
By \cref{lem:exists_cherry_in_Ramsey}, for every color $d\in [c]\setminus \{E(\{u,w\})\}$, the term $G[v,V_w,d]$ occurs in \cref{eq:last_step_lower_bound}. 
We assume that for all $w\in V(E)$ with respectively $u\in V(E)$ we have that, $G[v,V_w,E(\{u,w\})]\ge \frac{7}{8} |V_w|$. Otherwise, we get the lower bound
\begin{equation} \text{\cref{eq:last_step_lower_bound}} \ge 
    \left(\frac{1}{2} + \frac{1}{2\cdot 8^2(c-1)^2}\right)\left(\frac{1-\varepsilon_7}{r}\right)^2n^2 
    -\varepsilon_5 n^2 -rn.
\end{equation}
Then, there exists a unique function
$\alpha:V(E)\to[c]$ indicating that for each $w\in V(E)$, the set $v\ast V_w$ has at least $\frac{7}{8}|V_w|$ edges of color $\alpha(w)$. But by the maximality of the Ramsey graph, there will exist $u,w\in V(E)$ so that $\alpha(u)=E(\{u,w\}) = \alpha(w)$. Hence, we may lower bound $t_v^{(b)}$ by

\begin{equation} \frac{9}{16} \left(\frac{1-\varepsilon_7}{r}\right)^2n^2.
\end{equation}




    \medskip
    \noindent \textbf{Case 2. }   Assume now that there exists a vertex $w$ so that every enumeration $i_1,\dots,i_r$ of $V(E)$ with $i_r=w$ in \cref{alg:decrease_triangles} has $i_r$ as the vertex $u$ from \cref{enum:case_4_alg}. Choose an enumeration $i_1,\dots,i_r$ of $V(E)$ so that $i_r = w$ and $i_{r-1}=x$. Let $c_\ell$ denote the loop color of $E$. Then, considering again the second to last step, we have
\begin{align*}
    t_v^{(b)} \ge \binom{G[v,V_x,c_\ell]}{2} + \sum_{d\in [c]\setminus \{c_\ell\}}
    \sum_{\substack{j\in V(E)\setminus\{x,w\} \\ E(\{x,j\})=d}}
    G[v,V_x,d]|V_j|
\end{align*}
By \cref{lem:Degree_at_lest_two}, for every color $d\in [c]\setminus \{c_\ell\}$ in the first summation, there exists at least one non-zero term in the second summation. This means that we have
\begin{equation} \ge \binom{G[v,V_i,c_\ell]}{2} + (|V_i|-G[v,V_i,c_\ell])\frac{1-\varepsilon_7}{r}n
\end{equation}
If we had $G[v,V_i,c_\ell] \le \frac{3}{4}|V_i|$ for some $i$, then the minimum value for \cref{eq:case2_first_special_case} with respect to $G[v,V_i,c_\ell]$ would occur at $G[v,V_i,c_\ell] = \frac{3}{4}|V_i|$ and we would get 
\begin{equation} t^{(b)}_v\ge \left(\frac{9}{2\cdot 16} + \frac{1}{4}\right)\left(\frac{1-\varepsilon_7}{r}\right)^2n^2
     -\varepsilon_5 n^2 -rn.
\end{equation}
Assume that we always have $G[v,V_i,c_\ell] \ge \frac{3}{4}|V_i|$. Then we would get

\begin{equation} t_v^{(b)} \ge \sum_{i\in V(E)\setminus \{w\}}\left( \frac{3}{2\cdot 4}|V_i|^2\right)
    -\varepsilon_5 n^2 -rn
     \ge \left(\frac{1-\varepsilon_7}{r}\right)^2n^2
     -\varepsilon_5 n^2 -rn
\end{equation}

since $r \geq 3$.

\medskip

We note that all previous lower bounds for $t_v^{(b)}$, from \cref{eq:tvbLower_1} to \cref{eq:tvbLower_7}, are greater than our upper bound for $t_v^{(a)}$ stated in \cref{eq:triangle_upper_bound} by at least
\begin{equation*}
    \frac{1}{2^2\cdot 8^2(c-1)^2r^2}n^2.
\end{equation*}
when \whiteboxedchar{$\varepsilon_5$ and $\varepsilon_7$ are sufficiently small}.
We can destroy at most 
\begin{equation*}
    |V^*| \, \frac{1}{2^2\cdot 8^2(c-1)^2r^2}n^2 \le (p(\hat K_3; G)-\varsigma_n)\binom{n}{3}
\end{equation*}
triangles, that is we get an upper bound on $|V^\ast|$ depending on $p(\hat K_3; G)-\varsigma_n$. It follows that we have to recolor  at most
\begin{equation*}
    |V^*|n \le 2^2\cdot 8^2(c-1)^2r^2(p(\hat K_3; G)-\varsigma_n)\binom{n}{2}
\end{equation*}
edges.
\end{proof}

\begin{claim}
    After recoloring at most

    \begin{equation*}
         \frac{r+1}{3(2\delta_0-1)}(p(\hat K_3; G)-\varsigma_n)\binom{n}{2}
    \end{equation*}
    edges, the set $E^*$ will consist only of loop colored edges. \end{claim}
\begin{proof}
    Let $(x,y)\in E^\ast$ with $x\in V_i$, $y\in V_j$ and $E(\{x,y\})$ is not the loop color of $E$. By
    \cref{lem:exists_cherry_in_Ramsey} there exists at least one
    $k$ so that $E(\{i,k\}) = E(\{j,k\})=G(\{x,y\})$. By
    definition of $V_i$, both $x\ast F_k$ and $y\ast F_k$
    each have more than $\delta_0 |F_k|$ edges with color $G(\{x,y\})$ in $F_k$.
    Therefore, there are at least 
    \[
        (2\delta_0-1)|F_k|\ge (2\delta_0-1)\frac{1-\varepsilon_7}{r}n\ge (2\delta_0-1)\frac{1}{r+1}n
    \]
    monochromatic
    triangles containing $\{x,y\}$, where we have used \cref{lem:Claim_8} to lower bound $|F_k|$ and assume that \whiteboxedchar{$\varepsilon_7$ is sufficiently small} for the second inequality to hold. Note that each choice of $(x,y) \in
    E^\ast$ dictates its own set of of such monochromatic triangles, so we can sum them up without overcounting. If more than
    $\frac{r+1}{2\delta_0-1}(p(\hat K_3; G)-\varsigma_n)\binom{n}{2}/3$
    of these edges were to exist, they would lead to a decrease of the monochromatic triangle count of more than $(p(\hat K_3,G)-\varsigma_n)\binom{n}{3}$,
    a contradiction. Note that recoloring all of these edges $\{x,y\}$ respectively to $E(\{i,j\})$ \emph{simultaneously} does not create any additional triangles. Indeed, after recoloring, the only triangles left are those with the loop color. But we did not change any edge to the loop color and therefore we did not add any triangles. This establishes the claim.


\end{proof}

\begin{claim} There exists a $\delta'$ so that when $p(\hat K_3;G)-\varsigma_n\le \delta'$, at most $\frac{\varepsilon}{3}\binom{n}{2}$ edges in $\bigcup_{i\ne j}V_i\ast V_j$ need to be recolored so that the only monochromatic triangles in $G$ are contained within the $V_i$.
\end{claim}

\begin{proof}
Note that all triangles in $G$ that are not contained entirely within a $V_i$ are either within $V_i\cup V_j$ with $i\ne j$ and otherwise within $V_i\cup V_j\cup V_k$ with $i\ne j\ne k\ne i$. 
Denote by $H$ the graph with $V(H)=V(G)$ so that $e\in E(H)$ if and only if $e$ has the loop color of $E$ in $G$ and is contained in some $V_i\ast V_j$ with $i\ne j$. Note that $H$ is $r$-partite with parts of almost equal size. Applying the triangle removal lemma to $\varepsilon/6$ gives us a $\tilde\delta$ so that when $p(K_3;H)\le \tilde\delta$, all triangles in $H$ can be removed by deleting at most $\frac{\varepsilon}{6}\binom{n}{2}$ edges. Notice that when $p(\hat K_3;G)\le \varsigma_n+\tilde\delta$, we get $p(K_3;H)\le \tilde\delta$. Therefore, by recoloring at most $\frac{\varepsilon}{6}\binom{n}{2}$ edges, the only triangles left in $G$ are those with say two points in a $V_i$ and one point in a $V_j$.

For each $i\ne j$ let $H_{i,j} = H[V_i\ast V_j]$. Applying the removal lemma for paths of length two on three vertices with $\varepsilon / (6\binom{r}{2})$ gives us a $\hat\delta$ so that when $p(P_2,H_{i,j})\le \hat \delta$, at most $\varepsilon / (6\binom{r}{2})$ edges need to be recolored to make $H_{i,j}$ free of any $P_2$. Note that we have
\begin{align*}
    p(P_2;H_{i,j}) \le \frac{(p(\hat K_3;G)-\varsigma_n)\binom{n}{3}}{|H_{i,j}|}
    \le \frac{(p(\hat K_3;G)-\varsigma_n)\binom{n}{3}}
        {\binom{2\lfloor\frac{1-\varepsilon_7}{r}\rfloor n}{3}}
    \le\hat \delta.
\end{align*}

for every $i\ne j$ by \cref{lem:Claim_8}  assuming that

\begin{equation*}
    p(\hat K_3;G) \le \varsigma_n +
        \hat\delta\min_{n\ge n_0}
            \frac{\binom{2\lfloor\frac{1-\varepsilon_7}{r}\rfloor n}{3}}{\binom{n}{3}}.
\end{equation*}

Here we have assumed that \whiteboxedchar{$n_0$ is large enough} such that $\binom{2\frac{1-\varepsilon_7}{r}n}{3} > 0$. Hence we may choose
\begin{equation*}
    \delta ' =  \operatorname{min} \left( \tilde\delta, \hat\delta\inf_{n\ge n_0}
            \frac{\binom{2\lfloor\frac{1-\varepsilon_7}{r}n\rfloor }{3}}{\binom{n}{3}} \right)
\end{equation*}
to prove the claim.
\end{proof}

\begin{claim} There exists a $\delta''$ so that when $p(\hat K_3;G)-\varsigma_n\le \delta''$, at most
    $\frac{\varepsilon}{3}\binom{n}{2}$ edges need to be recolored to achieve that $||V_i|-|V_j||\le 1$ when $i\ne j$.
\end{claim}
\begin{proof}
Let $\rho_i = |V_i|/n$. Denote by $\rho\in \mathbb R^r$ the vector $\rho=(\rho_1,\dots,\rho_r)$. Let $R_n\subseteq\mathbb R^r$ be all vectors $s$ so that $\sum_i s_i=1$ and $ns$ is a vector of integers so that no two integers differ by more than 1.
For any given $\rho$, the number of vertices that need to be recolored is at most
\begin{equation} 2\min_{s\in R_n} \|\max(\rho-s,0)\|_1\binom{n}{2}
\end{equation}
where “$\max$" is interpreted as acting on each component. 
The triangle density is
    \begin{equation*}
        p(\hat K_3;G) = \frac{
        \sum_{i\in [r]}\binom{n\rho_i}{3}}{\binom{n}{3}}
        =
        Q_n(\rho)
    \end{equation*}
    which is a degree three polynomial in the $\rho_i$ for which $Q_n(s)=\varsigma_n$ when $s\in R_n$. 

We want to compute for a given $1>x>0$
\begin{align*}
    \min_{\min_{s\in R_n}\|\max(\kappa-s,0)\|_1=x} Q_n(\kappa)-\varsigma_n
\end{align*}
where $\kappa$ ranges over vectors in the standard simplex $\Delta^r$. By symmetry we may assume that 
\[
    s = \frac{1}{n}\left(\lceil \frac{n}{r}\rceil, \dots, \lceil \frac{n}{r}\rceil, \lfloor \frac{n}{r}\rfloor, \dots, \lfloor \frac{n}{r}\rfloor\right)
\]
and that $\kappa$ exceeds $s$ on the first $l$ coordinates. 
In this case, we find that the global minimum is at most $x^3/r^2$.








Therefore, when $0<\delta'' < \frac{1}{r^2}\left(\frac{\varsigma_n}{6}\right)^3$, this fulfills the assumptions of our claim: When $p(\hat K_3,G)\le \varepsilon_n+\delta''$ then necessarily $2\min_{2\in R_n}\|\max(\rho-s,0) \|_1\binom{n}{2}\le \frac{\varsigma_n}{6}$ which means that at most $\frac{\varsigma_n}{6}$ many edges need to be recolored to make the $V_i$ almost balanced. 
\end{proof}

It follows that, by picking 

\begin{align*}
    \delta &\le \min \left( \frac{\varepsilon_4}
    {2\left(\frac{1}{\varepsilon_1(1+\varepsilon_1)}+\frac{\binom{n_1}{6}}{s}\right)},
        \frac{\frac{\varepsilon}{9}}{\frac{r}{3}},\frac{\frac{\varepsilon}{9}}{2^2\cdot 8^2(c-1)^2r^2},\frac{\frac{\varepsilon}{9}}{\frac{r+1}{3(2\delta_0-1)}}, \delta', \delta''\right)
\end{align*}

with the individual components due to \cref{eq:beta_upper_bound}, \cref{lem:Claim_10}, \cref{lem:V_star_is_zero}, \cref{claim:f4}, \cref{claim:f5}, and \cref{claim:f6}, $G$ can be be turned into an element of $\mathcal{G}_{\operatorname{ex}}^{(c)}$ by recoloring at most $\varepsilon\binom{n}{2}$ edges, assuming that $p(\hat{K}_3; G) \leq \varsigma_n + \delta$. \hfill $\blacksquare$

\FOR{$\chi$ an irreducible character of $\Lambda_\tau$}
            \IF{ $\chi$ is rational}
                \STATE $C \gets C \cup \{\chi\}$
            \ELSIF{$\chi+\overline{\chi}$ is rational}
                \STATE $C \gets C \cup \{\chi+\overline{\chi}\}$
            \ELSE
                \STATE $\chi^\bot = \chi^\bot + \chi$
            \ENDIF

\FOR{k=1,\dots,r}
        \STATE $d^*\gets arg\,min_{d\in[c]} \begin{cases} \frac{1}{2}|V_{i_k}|&\text{if $d=c_\ell$} \\ \sum_{E(\{i_k,j\})=d} x_{j,d}&\text{otherwise} \end{cases}$
        \FOR{ $d\in [c]$}
            \IF{ $d \ne d^*$}
                \STATE $x_{i_k,d} \gets 0$
            \ELSE
                \STATE $x_{i_k,d} \gets |V_{i_k}|$
                \STATE $\alpha(i_k)=d$
            \ENDIF
        \ENDFOR
